tape( 'if a resolved starting index is greater than or equal to a resolved ending index, the function returns the input ndarray unchanged', opts, function test( t ) {
	var expected;
	var actual;
	var alpha;
	var start;
	var xbuf;
	var end;
	var x;

	xbuf = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
	x = vector( xbuf, 4, 1, 0 );
	alpha = scalar2ndarray( 5.0, {
		'dtype': 'float64'
	});
	expected = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );

	start = scalar2ndarray( 2, {
		'dtype': 'generic'
	});
	end = scalar2ndarray( 2, {
		'dtype': 'generic'
	});
	actual = dfill( [ x, alpha, start, end ] );
	t.strictEqual( actual, x, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( getData( actual ), expected ), true, 'returns expected value' );

	start = scalar2ndarray( 3, {
		'dtype': 'generic'
	});
	end = scalar2ndarray( 1, {
		'dtype': 'generic'
	});
	actual = dfill( [ x, alpha, start, end ] );
	t.strictEqual( actual, x, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( getData( actual ), expected ), true, 'returns expected value' );

	start = scalar2ndarray( 5, {
		'dtype': 'generic'
	});
	end = scalar2ndarray( 4, {
		'dtype': 'generic'
	});
	actual = dfill( [ x, alpha, start, end ] );
	t.strictEqual( actual, x, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( getData( actual ), expected ), true, 'returns expected value' );

	start = scalar2ndarray( 0, {
		'dtype': 'generic'
	});
	end = scalar2ndarray( -10, {
		'dtype': 'generic'
	});
	actual = dfill( [ x, alpha, start, end ] );
	t.strictEqual( actual, x, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( getData( actual ), expected ), true, 'returns expected value' );

	t.end();
});

